[CmdletBinding()]
param([string]$RepositoryRoot = '')
if ([string]::IsNullOrWhiteSpace($RepositoryRoot)) { $RepositoryRoot = Split-Path -Parent (Split-Path -Parent $PSScriptRoot) }
$ErrorActionPreference='Stop';$ops=Join-Path (Resolve-Path -LiteralPath $RepositoryRoot).Path 'docs/etc/operations';$work=@(Import-Csv (Join-Path $ops 'm0-t277-s2-source-form-worklist.tsv') -Delimiter "`t"|?{$_.caller_package -in @('vdmredir','wow32')});$l=@(Import-Csv (Join-Path $ops 'm0-t277-s6-redir-wow-disposition-ledger.tsv') -Delimiter "`t")
if($work.Count -ne 17 -or $l.Count -ne 17){throw "Expected 17 rows; work=$($work.Count), ledger=$($l.Count)."};if(Compare-Object ($work.work_item_id|Sort-Object) ($l.work_item_id|Sort-Object)){throw 'S6 ledger differs from the remaining S2 work set.'};if(($l.work_item_id|Sort-Object -Unique).Count -ne 17){throw 'S6 work IDs are not unique.'};if(($l|?{$_.audit_state -ne 'source-form-family-reviewed; implementation-not-enabled'}).Count){throw 'S6 must not enable an implementation state.'};if(($l.family|Sort-Object -Unique).Count -ne 8){throw 'Expected eight Redirector/WOW families.'};if(@($l|?{$_.family -eq 'Redirector-guest-address-lease' -and $_.mapping_rule -notlike 'scoped session guest_memory*'}).Count){throw 'Redirector address conversion must use the session guest-memory lease.'};if(@($l|?{$_.family -eq 'WOW-bounded-machine-run' -and $_.owner -ne 'adapter-softpc -> adapter-bochs'}).Count){throw 'WOW machine run must reuse S3 owner.'};if(@($l|?{$_.family -eq 'WOW-serial-endpoint' -and $_.mapping_rule -notlike 'session host_resource*'}).Count){throw 'WOW serial endpoint must use session host_resource mapping.'};Write-Host "T277 S6 Redirector/WOW disposition passed: work-items=$($l.Count); families=8."
